<script setup lang="ts">
import type { SubmissionPayload } from "~/composables/useSubmissionWizard";
const props = defineProps<{ draftId: string; media: SubmissionPayload["media"]; description: string; error?: string }>();
const emit = defineEmits<{ "update:media": [value: SubmissionPayload["media"]]; "update:description": [value: string] }>();
const uploader = useMediaUpload();
function patch(clientId: string, change: Partial<SubmissionPayload["media"][number]>) { emit("update:media", props.media.map((item) => item.clientId === clientId ? { ...item, ...change } : item)); }
async function selectFiles(event: Event) { const input = event.target as HTMLInputElement; const files = [...(input.files ?? [])].slice(0, 10 - props.media.length); for (const file of files) { const item = { clientId: crypto.randomUUID(), kind: file.type.startsWith("video/") ? "video" as const : "image" as const, name: file.name, size: file.size, contentType: file.type, status: "staged" as const, previewUrl: URL.createObjectURL(file), cover: props.media.length === 0 }; emit("update:media", [...props.media, item]); await nextTick(); if (props.draftId) void uploader.upload(file, props.draftId, item, (change) => patch(item.clientId, change)); } input.value = ""; }
async function removeItem(item: SubmissionPayload["media"][number]) { if (item.assetId) await uploader.remove(item.assetId).catch(() => undefined); if (item.previewUrl) URL.revokeObjectURL(item.previewUrl); const next = props.media.filter((file) => file.clientId !== item.clientId); const first = next[0]; if (first && !next.some((file) => file.cover)) first.cover = true; emit("update:media", next); }
async function makeCover(clientId: string) { const next = props.media.map((item) => ({ ...item, cover: item.clientId === clientId })); emit("update:media", next); if (props.draftId) await uploader.reorder(props.draftId, next).catch(() => undefined); }
</script>
<template><section><h2>تصویر، ویدیو و توضیحات</h2><p class="submission-hint">تا ۱۰ فایل؛ تصاویر حداکثر ۲۰ و ویدیو حداکثر ۲۰۰ مگابایت. فایل‌ها مستقیم و امن بارگذاری می‌شوند.</p><label class="media-drop"><input type="file" accept="image/jpeg,image/png,image/webp,video/mp4" multiple @change="selectFiles"><strong>افزودن تصویر یا ویدیو</strong><span>JPG، PNG، WebP یا MP4</span></label><ul class="staged-media media-upload-list"><li v-for="item in media" :key="item.clientId"><img v-if="item.previewUrl && item.kind === 'image'" :src="item.previewUrl" alt=""><span v-else>{{ item.kind === 'image' ? 'تصویر' : 'ویدیو' }}</span><div><strong>{{ item.name }}</strong><small>{{ item.status === 'processing' ? 'در صف بررسی و پردازش' : item.status === 'failed' ? 'خطا در بارگذاری' : item.status === 'ready' ? 'آماده' : item.status === 'uploading' ? 'در حال بارگذاری' : 'در حال آماده‌سازی' }}</small><progress v-if="item.progress !== undefined && item.status !== 'failed'" :value="item.progress" max="100"></progress></div><button v-if="!item.cover" type="button" @click="makeCover(item.clientId)">کاور</button><b v-else>کاور</b><button type="button" @click="removeItem(item)">حذف</button></li></ul><label class="submission-description"><span>توضیحات *</span><textarea :value="description" rows="7" maxlength="4000" placeholder="ویژگی‌ها و شرایط معامله را شفاف بنویسید" @input="emit('update:description', ($event.target as HTMLTextAreaElement).value)"></textarea><small v-if="error" class="field-error">{{ error }}</small></label></section></template>
